// DAG DP - count paths from source to target using topological order
function countPaths(n, edges, source, target) {
  const adj = Array.from({ length: n }, () => []);
  const inDegree = new Array(n).fill(0);
  for (const [u, v] of edges) {
    adj[u].push(v);
    inDegree[v]++;
  }

  // Kahn's topological sort
  const queue = [];
  for (let i = 0; i < n; i++) if (inDegree[i] === 0) queue.push(i);

  const dp = new Array(n).fill(0);
  dp[source] = 1; // one way to be at source
  let head = 0;

  while (head < queue.length) {
    const u = queue[head++];
    for (const v of adj[u]) {
      dp[v] += dp[u]; // propagate path count
      if (--inDegree[v] === 0) queue.push(v);
    }
  }
  return dp[target];
}

// Bounded-step DP (cheapest flight with at most K stops)
function findCheapestPrice(n, flights, src, dst, k) {
  let dp = new Array(n).fill(Infinity);
  dp[src] = 0;

  for (let step = 0; step <= k; step++) {
    const prev = [...dp]; // COPY before updating - prevent intra-step bleeding
    for (const [u, v, w] of flights) {
      if (prev[u] !== Infinity) {
        dp[v] = Math.min(dp[v], prev[u] + w);
      }
    }
  }
  return dp[dst] === Infinity ? -1 : dp[dst];
}
